import{at as e,it as t,s as n,yt as r}from"./chunks/framework.qHnXdyAW.js";var i=JSON.parse(`{"title":"在线工具导航与 V2Ray 转 Clash 页面迁移设计","description":"为 VitePress 顶部导航增加在线工具菜单，并迁移 V2Ray 转 Clash 订阅页面。","frontmatter":{"title":"在线工具导航与 V2Ray 转 Clash 页面迁移设计","description":"为 VitePress 顶部导航增加在线工具菜单，并迁移 V2Ray 转 Clash 订阅页面。"},"headers":[],"relativePath":"superpowers/specs/2026-07-28-online-tools-navigation-design.md","filePath":"superpowers/specs/2026-07-28-online-tools-navigation-design.md","lastUpdated":1786080858000}`),a={name:`superpowers/specs/2026-07-28-online-tools-navigation-design.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="在线工具导航与-v2ray-转-clash-页面迁移设计" tabindex="-1">在线工具导航与 V2Ray 转 Clash 页面迁移设计 <a class="header-anchor" href="#在线工具导航与-v2ray-转-clash-页面迁移设计" aria-label="Permalink to “在线工具导航与 V2Ray 转 Clash 页面迁移设计”">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to “目标”">​</a></h2><p>在站点顶部增加“在线工具”下拉菜单，将现有 V2Ray 转 Clash 订阅转换工具从“知识碎片”分类迁移到独立的在线工具分类，并保持旧链接可用。</p><h2 id="页面与导航" tabindex="-1">页面与导航 <a class="header-anchor" href="#页面与导航" aria-label="Permalink to “页面与导航”">​</a></h2><ul><li>新建 <code>docs/tools/index.md</code>，作为在线工具分类入口。</li><li>将正式工具页迁移到 <code>docs/tools/v2ray-to-clash.md</code>，新地址为 <code>/tools/v2ray-to-clash</code>。</li><li>顶部导航新增“在线工具”下拉菜单，菜单项“V2Ray 转 Clash 订阅”直接指向新地址。</li><li>侧边栏增加 <code>/tools/</code> 分类扫描，使在线工具页面沿用站点现有导航方式。</li><li>从 <code>docs/other/index.md</code> 移除“在线工具”小节，避免同一工具归属两个分类。</li></ul><h2 id="旧地址兼容" tabindex="-1">旧地址兼容 <a class="header-anchor" href="#旧地址兼容" aria-label="Permalink to “旧地址兼容”">​</a></h2><p>原页面 <code>docs/other/v2ray-to-clash.md</code> 改为迁移提示页，保留必要的 <code>title</code> frontmatter，并提供新页面链接。旧链接 <code>/other/v2ray-to-clash</code> 因此不会直接失效，转换组件只在新页面加载。</p><h2 id="页面内容" tabindex="-1">页面内容 <a class="header-anchor" href="#页面内容" aria-label="Permalink to “页面内容”">​</a></h2><p>迁移后的页面保留现有标题、说明、页面样式类和 <code>V2rayToMihomo</code> 组件，不修改转换逻辑、交互或配置生成行为。在线工具分类入口以简短列表展示工具名称与用途。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to “验证”">​</a></h2><ul><li>运行现有 V2Ray 转 Mihomo 测试，确认页面迁移未影响转换模块。</li><li>运行 <code>npm run docs:build</code>，确认新旧路径、导航与 Markdown 均能正常构建。</li><li>检查顶部“在线工具”下拉项指向 <code>/tools/v2ray-to-clash</code>。</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};